import unittest,subprocess
class WaveEvidenceDeltaTests(unittest.TestCase):
 def node(self,code):
  r=subprocess.run(['node','-e',"const assert=require('assert/strict'),E=require('./web_r4/loading-engine.js'),C=require('./web_r4/loading-coach.js'),c=require('./web_r4/loading-data.json');function run(i=0,period='LEVEL1',s={},risk='BALANCED'){let x=E.exampleInput(c,i);x.schema_version='lol-coach-loading-input-v3';x.preferences={risk};x.scenario={standard:'lane-standard-v1',overrides:s};const r=E.analyze(x,c);r.coach=C.evaluate(r,c,x.scenario,period);return r;}"+code],capture_output=True,text=True);self.assertEqual(r.returncode,0,r.stderr[-2500:])
 def test_source_scoped_enemy_wave_tradeoff_not_level_or_kill_guarantee(self):
  self.node("const r=run(),b=r.coach.planboard;assert(b.wave.opponent_response,'enemy wave response missing');assert(b.wave.opponent_response.includes('공간'));assert(b.wave.claim_ids.includes('A-WAVE-SPACE'));assert(b.matchup_playbook.theirs.purpose.includes('거리'));assert.equal(b.fight.kill,'UNDETERMINED');assert(b.evidence.claims.find(c=>c.id==='A-WAVE-SPACE'));assert(b.composition.ours&&b.composition.theirs);")
 def test_reverse_example_is_real_input_not_fixed_result(self):
  self.node("const x=E.exampleInput(c,5);assert.equal(x.own_champion,'Kaisa');assert.equal(x.allies.find(p=>p.position==='SUPPORT').champion,'Alistar');assert.equal(x.enemies.find(p=>p.position==='BOTTOM').champion,'Yunara');assert.equal(E.analyze(x,c).coach.planboard.coverage.matchup,'BR');")
 def test_reverse_duo_has_its_own_resource_purpose_without_fake_inverted_strength(self):
  self.node("let x=E.exampleInput(c,2);[x.allies,x.enemies]=[x.enemies,x.allies];x.own_champion='Kaisa';const r=E.analyze(x,c),b=r.coach.planboard;assert.equal(r.coach.supported,false);assert.equal(b.coverage.matchup,'BR');assert.equal(b.coverage.status,'CONDITIONAL_REFERENCE');assert(b.lane.overall_goal.includes('체력'));assert.equal(b.wave.plan_id,'TRIM_RECEIVE');assert(b.matchup_playbook.ours.means.includes('카이사'));assert(b.matchup_playbook.theirs.means.includes('룰루'));assert(!b.matchup_playbook.ours.means.includes('박치기(W)'));assert(r.coach.periods.every(p=>Object.values(p.metrics).every(m=>m.assessment==='INSUFFICIENT')));const later=C.evaluate(r,c,null,'LEVEL2').planboard;assert.notEqual(b.lane.milestone.goal,later.lane.milestone.goal);assert(later.matchup_playbook.ours.means.includes('박치기(W)'));assert.equal(b.wave.diagram.supported,false);const low=C.evaluate(r,c,{standard:'lane-standard-v1',overrides:{resources:'LOW'}}).planboard;assert.equal(low.matchup_playbook.ours.means,low.wave.combat);x.patch='1.1';assert.equal(E.analyze(x,c).coach.planboard.coverage.status,'UNSUPPORTED');")
if __name__=='__main__':unittest.main()
